INSERT INTO clinic_record_tag (title, description, apply_rule) VALUES
('清灰换硅脂', '处理因内部积灰或散热硅脂老化导致的散热问题。典型症状：机身发烫、风扇持续高速运转噪音大、高负载（游戏/渲染）时降频卡顿、CPU/GPU 温度过高、运行一段时间后自动关机或重启。服务内容为拆机清灰并重新涂抹散热硅脂。边界：风扇本身损坏（异响/不转）归「换风扇」；温度正常、纯软件卡顿不属本类。', '清灰, 灰尘, 除尘, 硅脂, 散热, 过热, 发热, 烫, 高温, 温度高, 降频, 风扇狂转, 风扇声音大, 自动关机, 自动重启, 散热不好'),
('换风扇', '风扇硬件故障，需更换或维修风扇。典型症状：风扇异响（咔咔/嗡嗡/尖锐摩擦声）、风扇不转、开机报 fan error、转速异常导致散热失效。与「清灰换硅脂」区别：本类针对风扇机械/电气故障，而非单纯积灰或硅脂老化；"风扇声音大"需结合是否需换风扇判断。', '风扇, 换风扇, 风扇异响, 风扇不转, 风扇坏, 风扇故障, fan error, 噪音, 异响, 摩擦声'),
('重装系统', '操作系统故障需重装/恢复系统。典型症状：系统无法启动、蓝屏(BSOD)、黑屏、开机卡死、进不去系统、系统文件损坏、中病毒/木马、极度缓慢且无法常规修复、更新失败导致无法开机。服务内容为备份数据后重装系统并装驱动。边界：仅想装双系统归「安装双系统」。', '重装系统, 装系统, 系统重装, 蓝屏, 黑屏, 开不了机, 进不去系统, 系统崩溃, 系统损坏, 崩溃, 死机, 卡死, 中毒, 木马, 无法启动, 无法开机'),
('加硬盘/内存', '硬件扩容：加装/更换硬盘（机械/固态）或内存条。典型描述：想加硬盘/内存、内存不够、扩内存、加 SSD、换更大硬盘、存储不足。服务内容为拆机加装/更换并完成分区或系统迁移。边界：软件层面的文件清理释放空间不属本类。', '硬盘, 内存, 加装, 扩容, 加硬盘, 加内存, 换硬盘, 换内存, 升级内存, 升级硬盘, SSD, 固态, 机械硬盘, 存储, 空间不足'),
('网络问题', '网络连接软硬件问题：连不上网、WiFi 连不上、有线不通、网速极慢、频繁掉线、网卡驱动异常、代理/VPN 无法连接、校园网认证问题、路由器/交换机配置。服务内容为排查并修复网络连接。边界：核心是网络而非系统/软件本身。', '网络, 上网, wifi, WiFi, WIFI, 无线, 网卡, 连不上网, 上不了网, 断网, 掉线, 网速, 校园网, 认证, 代理, VPN, vpn, 路由器, 交换机, 有线, 宽带'),
('soildworks安装', '安装 SolidWorks 三维建模软件。典型描述：装 SolidWorks/SW、装不上、激活失败、闪退。注意拼写变体（solidworks / soildworks / solidwork）。服务内容为下载安装、安装并激活/验证。边界：其它 CAD（AutoCAD、CATIA）归「软件安装」。', 'solidworks, soildworks, solidwork, sw, SW, SolidWorks, SOLIDWORKS'),
('软件安装', '安装除 SolidWorks 与操作系统外的各类软件（办公/开发/设计/专业/游戏）。典型描述：帮我装 XX、XX 装不上、需要安装 XX、缺 XX 环境。服务内容为下载、安装、激活并配置。边界：SolidWorks 归「soildworks安装」；系统安装归「重装系统」/「安装双系统」。', '软件, 装软件, 安装软件, 装个, 安装, 环境, 配置, 开发环境, 装不上, 软件安装'),
('安装双系统', '一台电脑装两个及以上系统，通常 Windows + Linux（Ubuntu/Debian 等）。典型描述：想装双系统、Windows 和 Linux 共存、加装 Linux、装 Ubuntu、分区装第二系统；grub 引导修复也常伴随。服务内容为分区、装第二系统、配置引导。边界：仅一个系统（如只换掉原系统）归「重装系统」。', '双系统, Linux, Ubuntu, ubuntu, 引导, grub, 分区, 第二系统, 双引导'),
('清理C盘', '清理系统盘（C 盘）空间不足问题。典型症状：C 盘爆满/变红、磁盘空间不足提示、需清理垃圾文件/缓存/临时文件、卸载无用软件、把文件迁移到其它盘。服务内容为清理垃圾、卸载冗余软件、迁移文件、清理缓存。边界：加装硬盘/内存的扩容需求归「加硬盘/内存」；因 C 盘满导致的系统卡顿也归本类。', '清理C盘, C盘, c盘, 系统盘, 磁盘空间不足, 空间不足, 垃圾, 缓存, 临时文件, C盘满, C盘爆'),
('其它问题', '兜底分类，用于以上都不适用的维修需求，如配件咨询、数据恢复、屏幕/键盘/电池等硬件问题、外观清洁、售前售后咨询等。无法归入任何具体类别时使用。', ''),
('G15', '戴尔 G15 系列笔记本专属标签。当用户填写的笔记本型号属于戴尔 G15 系列时使用（可能写作 dell G15、Dell G15、G15 5510/5515/5520 等，大小写可能不一致）。可与问题类别标签并存（如既是 G15 又要清灰）。', 'model:g15, dell g15, dellg15'),
('蛟龙16', '蛟龙16 笔记本专属标签（机械革命等品牌）。当笔记本型号包含「蛟龙16」时使用，可与问题类别标签并存。', 'model:蛟龙16')
